import{_ as o,l as s,o as e,c as n,v as t,p as l,x as r,d,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"优先级反转","description":"","frontmatter":{"title":"优先级反转","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/priority-inversion.md","filePath":"cs/priority-inversion.md","lastUpdated":1789023840000}'),h={name:"cs/priority-inversion.md"};function _(m,a,E,u,f,A){const i=s("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="优先级反转" tabindex="-1">优先级反转 <a class="header-anchor" href="#优先级反转" aria-label="Permalink to &quot;优先级反转&quot;">​</a></h1><div class="epigraph"><p>低优先级线程占着锁，中优先级线程占着 CPU，高优先级线程忙等或睡眠等锁——优先级在锁上被翻转了。</p><footer>—— 据 Silberschatz et al., Operating System Concepts；火星探路者故障中的优先级反转讨论整理</footer></div><p><a href="/cs/mlfq">上一课</a>让高档任务先跑。一旦共享数据要互斥，低优先级可以持锁；高优先级要同一把锁就只能等。若此时中优先级可运行且不碰那把锁，它会抢走低优先级的 CPU，于是锁迟迟不放，高优先级比中优先级还晚——<strong>优先级反转</strong>。本课只诊断现象，不把继承协议写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>调度器按优先级选 runqueue 队头，它看不见锁。高优先级不是死锁（低优先级最终可能跑完并放锁），但期限可以丢。<a href="/cs/realtime-sched">实时调度对照</a>点过这名字，当时没有锁课。缺口是：在已经有优先级的系统里，<strong>锁把优先级序与逻辑依赖拧反</strong>。本课仍不实现自旋锁，只假设存在互斥。</p><p><span class="marginnote">无界反转：任意多个中优先级可以轮流挡住持锁者。有界反转：只有持锁者自己的剩余临界区，前提是中优先级不能插在持锁者与放锁之间。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>三线程：\\(L\\) 持锁，\\(H\\) 等锁，\\(M\\) 不碰锁但优先级在二者之间。时间线： \\(L\\) 被 \\(M\\) 抢占 → \\(H\\) 无法前进。对照：若禁止 \\(M\\) 在 \\(L\\) 持锁期间跑（或让 \\(L\\) 暂时等于 \\(H\\) 的优先级），则 \\(H\\) 的等待只剩临界区长度。本课只画清问题，把「暂时抬高」留给下一课。</p>',8)),(e(),l(c,null,{default:r(()=>[p(i,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20L%5B%22%E4%BD%8E%E4%BC%98%E5%85%88%E7%BA%A7%E6%8C%81%E9%94%81%22%5D%20--%3E%20M%5B%22%E4%B8%AD%E4%BC%98%E5%85%88%E7%BA%A7%E5%8D%A0%20CPU%22%5D%0A%20%20H%5B%22%E9%AB%98%E4%BC%98%E5%85%88%E7%BA%A7%E7%AD%89%E9%94%81%22%5D%20--%3E%20L%0A%20%20M%20--%3E%20INV%5B%22H%20%E6%AF%94%20M%20%E8%BF%98%E6%99%9A%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>ISR 里拿锁会把反转变成关中断时间，更难看；那是锁与 IRQ 课的对象。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>反转说明「优先级」只描述调度器的意愿，不描述资源上的等待图。MLFQ 的档位、实时 FIFO、nice，只要能和锁相遇，都会中招。公平调度的 vruntime 也会因锁而让「该跑的人」跑不成，只是不叫优先级反转而叫锁争用；本课对象是显式优先级。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把探路者软件的补丁当操作手册，不引入优先级天花板的全部证明。死锁四条件更后；反转的等待图无环也可发生。用户态锁同样能反转，只要内核按优先级调度那些线程。</p><p>后课默认：反转是锁与优先级的结构后果。如何用继承或天花板把等待有界化，下一课讲 PI 与 PCP。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>反转：低优先级持锁 + 中优先级抢 CPU ⇒ 高优先级被拖。</li><li>不是死锁，但期限可丢；无界时中优先级可一直插队。</li><li>继承与天花板是下一课。</li><li>出处：Silberschatz et al., <em>OSC</em>；实时系统教材中的 PI 案例。</li></ul>',8))])}const C=o(h,[["render",_]]);export{B as __pageData,C as default};
